result = await mcp.call_tool("tools", "ox-bridge-write", {"path": "app.py", "content": """"Signup endpoint stub with a custom validation-error envelope.

POST /signup accepts {"email": str, "age": int}.
On validation failure it returns HTTP 422 with:

    {"error": {"code": "validation_error", "fields": {"<field>": "<reason>"}}}

The mobile client parses this envelope, so we never emit FastAPI's
default {"detail": [...]} shape -- both our own checks and Pydantic's
request parsing funnel through the same handler.
"""

import re

from fastapi import FastAPI, Request
from fastapi.exceptions import RequestValidationError
from fastapi.responses import JSONResponse
from pydantic import BaseModel

# Sane-enough email check: local part, @, domain labels, TLD of 2+ letters.
EMAIL_REGEX = re.compile(r"^[A-Za-z0-9._%+-]+@[A-Za-z0-9-]+(\.[A-Za-z0-9-]+)*\.[A-Za-z]{2,}$")

MIN_AGE = 13
MAX_AGE = 120


class ValidationFailure(Exception):
    """Carries per-field reasons to be rendered by the exception handler."""

    def __init__(self, fields: dict[str, str]):
        self.fields = fields
        super().__init__("; ".join(f"{k}: {v}" for k, v in fields.items()))


class SignupRequest(BaseModel):
    email: str
    age: int


def validate_signup(payload: SignupRequest) -> None:
    fields: dict[str, str] = {}
    if not EMAIL_REGEX.fullmatch(payload.email):
        fields["email"] = "invalid email address"
    if not (MIN_AGE <= payload.age <= MAX_AGE):
        fields["age"] = f"age must be between {MIN_AGE} and {MAX_AGE}"
    if fields:
        raise ValidationFailure(fields)


def error_response(fields: dict[str, str]) -> JSONResponse:
    return JSONResponse(
        status_code=422,
        content={"error": {"code": "validation_error", "fields": fields}},
    )


app = FastAPI()


@app.exception_handler(ValidationFailure)
async def validation_failure_handler(request: Request, exc: ValidationFailure) -> JSONResponse:
    return error_response(exc.fields)


@app.exception_handler(RequestValidationError)
async def request_validation_handler(
    request: Request, exc: RequestValidationError
) -> JSONResponse:
    # Malformed body / wrong types get the same envelope so the mobile
    # client only ever has to parse one error shape.
    fields = {
        ".".join(str(loc) for loc in err["loc"][1:]) or "body": err["msg"]
        for err in exc.errors()
    }
    return error_response(fields)


@app.post("/signup")
async def signup(payload: SignupRequest) -> dict:
    validate_signup(payload)
    return {"status": "ok", "email": payload.email}
"})
