    body = response.json()
    # Exactly the envelope the mobile client parses -- no FastAPI "detail".
    assert set(body) == {"error"}
    assert body["error"]["code"] == "validation_error"
    assert isinstance(body["error"]["fields"], dict)
    return body["error"]["fields"]


def test_signup_happy_path(client):
    response = client.post("/signup", json={"email": "user@example.com", "age": 30})
    assert response.status_code == 200
    assert response.json() == {"status": "ok", "email": "user@example.com"}


